style.css:
body {
  margin: 0;
  height: 100vh;
  font-family: 'Arial', sans-serif;

  /* Gradient sky (Manchester vibe) */
  background: linear-gradient(
    to bottom,
    #2c3e50 0%,   /* dark blue */
    #4b79a1 40%,  /* faded blue */
    #283048 100%  /* deep night tone */
  );

  /* Subtle grain overlay */
  position: relative;
  overflow: hidden;
}

body::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;

  background-image: url("https://www.transparenttextures.com/patterns/asfalt-light.png");
  opacity: 0.2;
  animation: grainMove 8s infinite linear;
}

/* Optional: faint spotlight effect */
body::before {
  content: "";
  position: absolute;
  top: -20%;
  left: -20%;
  width: 140%;
  height: 140%;

  background: radial-gradient(circle at center, rgba(255,255,255,0.08), transparent 60%);
}

/* Grain animation */
@keyframes grainMove {
  0% { transform: translate(0, 0); }
  50% { transform: translate(-10%, -10%); }
  100% { transform: translate(0, 0); }
}
